# Terminal Noir for fzf. https://terminalnoir.web.app
# Generated by scripts/build from palette/palette.json.
# Source it from your shell rc. bg:-1 keeps the terminal background.
export FZF_DEFAULT_OPTS="${FZF_DEFAULT_OPTS:+$FZF_DEFAULT_OPTS }--color=bg:-1,fg:#F4F4F5,hl:#F5A623,bg+:#18181B,fg+:#F4F4F5,hl+:#F5A623,gutter:-1,info:#A1A1AA,prompt:#F5A623,pointer:#F5A623,marker:#34D399,spinner:#F5A623,header:#A1A1AA,border:#64646B,separator:#64646B,scrollbar:#64646B,query:#F4F4F5"
